/* Menata ulang `items` satu Sub-Tier sesuai KOTOBA_CATEGORY_DEFS, lalu
   mengembalikan array baru + daftar "run" (kategori, indeks awal, jumlah)
   yang dipakai renderVocabTables() buat nyisipin baris pemisah kategori.
   Array aslinya TIDAK dimutasi, jadi Mode Kuis tetap pakai urutan lama. */
function vocabWordMatchesRule(
  entry: KotobaEntry,
  rule: string | [string, string],
) {
  // rule biasa cuma string bacaan (mis. "あつい") — cocok ke SEMUA entri
  // dengan bacaan itu. Kalau ada 2 kata beda arti tapi bacaan sama persis
  // (mis. あつい "暑い" cuaca vs あつい "熱い" benda/makanan), pakai rule
  // berupa pasangan [bacaan, kanji] biar keduanya bisa dipisah ke kategori
  // yang beda — kanji-nya (entry[6]) yang jadi pembeda.
  if (Array.isArray(rule)) return entry[0] === rule[0] && entry[6] === rule[1];
  return entry[0] === rule;
}

type CategoryDef = {
  label: Bilingual;
  words: (string | [string, string])[];
};

type CategoryRun = {
  label: Bilingual;
  start: number;
  count: number;
};

type CategorizedResult = {
  items: KotobaEntry[];
  runs: CategoryRun[] | null;
};

function buildCategorizedVocab(
  tierKey: string,
  items: KotobaEntry[],
): CategorizedResult {
  const defs = (KOTOBA_CATEGORY_DEFS as Record<string, CategoryDef[]>)[tierKey];
  if (!defs) return { items, runs: null };

  const buckets: { label: Bilingual; items: KotobaEntry[] }[] = defs.map(
    (d) => ({
      label: d.label,
      items: [],
    }),
  );
  const leftovers: KotobaEntry[] = [];

  items.forEach((entry) => {
    const idx = defs.findIndex((d) =>
      d.words.some((rule) => vocabWordMatchesRule(entry, rule)),
    );
    if (idx >= 0) buckets[idx].items.push(entry);
    else leftovers.push(entry);
  });

  if (leftovers.length) {
    buckets.push({ label: { en: "Other", id: "Lainnya" }, items: leftovers });
  }

  const ordered: KotobaEntry[] = [];
  const runs: CategoryRun[] = [];
  buckets.forEach((b) => {
    if (!b.items.length) return;
    runs.push({
      label: b.label,
      start: ordered.length,
      count: b.items.length,
    });
    b.items.forEach((entry) => ordered.push(entry));
  });

  return { items: ordered, runs };
}

